CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, phone TEXT UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'restaurant', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS restaurants (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, phone TEXT, address TEXT, logo_url TEXT, trial_ends_at TEXT NOT NULL, subscription_ends_at TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tables (id INTEGER PRIMARY KEY AUTOINCREMENT, restaurant_id INTEGER NOT NULL, name TEXT NOT NULL, capacity INTEGER NOT NULL DEFAULT 2, active INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(restaurant_id) REFERENCES restaurants(id));
CREATE TABLE IF NOT EXISTS hours (id INTEGER PRIMARY KEY AUTOINCREMENT, restaurant_id INTEGER NOT NULL, weekday INTEGER NOT NULL, open_time TEXT, close_time TEXT, enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(restaurant_id,weekday), FOREIGN KEY(restaurant_id) REFERENCES restaurants(id));
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY AUTOINCREMENT, restaurant_id INTEGER NOT NULL, table_id INTEGER, customer_name TEXT NOT NULL, customer_phone TEXT NOT NULL, booking_date TEXT NOT NULL, booking_time TEXT NOT NULL, guests INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(restaurant_id) REFERENCES restaurants(id), FOREIGN KEY(table_id) REFERENCES tables(id));
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_bookings_restaurant_date ON bookings(restaurant_id,booking_date);
CREATE INDEX IF NOT EXISTS idx_restaurants_slug ON restaurants(slug);
